test('retention claim CAS rejects authority withdrawal at the actual mutation boundary',async t=>{const f=await acceptedFixture(t);await enable(f);const prepared=await plan(f);let raced;f.db.beforeMutation=()=>{f.sql.prepare("UPDATE app_state SET value=json_set(value,'$.scope.scope','preparation') WHERE key=?").run('media_scope_v1:'+f.id);raced=snapshot(f.sql);};await assert.rejects(()=>p.applySiteRetention(f.id,{plan_id:prepared.plan_id,max_objects:16},actor),status(409));assert.ok(raced);assert.deepEqual(snapshot(f.sql),raced);assert.equal(f.r2.deletedKeys.length,0);});

