test('GLM real revoke inside retention plan INSERT CAS preserves revoke and creates no stale plan',async t=>{const f=await acceptedFixture(t,{glm:true});await enable(f);let raced;f.db.beforeMutation=async()=>{await p.revokeOwnerEditorialDelivery(f.id,OWNER,{request_id:'SYNTHETIC-retention-race-revoke',authorization_id:f.editorialId,note:'SYNTHETIC revoke injected at actual plan mutation'});raced=snapshot(f.sql);};await assert.rejects(()=>plan(f),status(409));assert.ok(raced);assert.deepEqual(snapshot(f.sql),raced);assert.equal(f.r2.deletedKeys.length,0);});

test('an old five-role lookalike without the exact owner closure proof cannot use the exception',async t=>{const f=await acceptedFixture(t);await enable(f);f.sql.prepare("DELETE FROM production_reviews WHERE job_id=? AND decision='owner_post_video_delivery_complete_v1'").run(f.id);const before=snapshot(f.sql);await assert.rejects(()=>plan(f),status(409));assert.deepEqual(snapshot(f.sql),before);assert.equal(f.r2.deletedKeys.length,0);});

test('legacy six-role approved version cleanup remains supported without enrolling it in the five-role exception',async t=>{const f=await legacyCompletedFixture(t),{started,ids}=await legacyStageVersion(f);await p.commitApprovedNativeVersion(LEGACY_ID,{version_request_id:started.version.version_id,archives:ids},actor);f.id=LEGACY_ID;await enable(f);const before=await p.getJob(LEGACY_ID),prepared=await plan(f);assert.deepEqual(Object.keys(prepared.keep).sort(),[...SIX].sort());assert.equal(prepared.candidates.length,6);assert.equal(await p.completedOwnerPostVideoDelivery(before,OWNER),null);const done=await finish(f,prepared);assert.equal(done.status,'complete');for(const sid of Object.values(f.oldArchives))assert.equal(keysFor(f,sid).length,0);for(const role of SIX){const result=await p.readSiteArchiveFile(LEGACY_ID,ids[role],OWNER),bytes=Buffer.from(await new Response(result.body).arrayBuffer()),expected=role==='video'?f.nextBytes:['source_bundle','complete_bundle'].includes(role)?Buffer.from('PK\x03\x04SYNTHETIC new '+role):f.oldBytes[role];assert.deepEqual(bytes,expected,role);}assert.deepEqual(protectedJob(await p.getJob(LEGACY_ID)),protectedJob(before));});

test('legacy six-role route still refuses a missing current source archive',async t=>{const f=await legacyCompletedFixture(t),{started,ids}=await legacyStageVersion(f);await p.commitApprovedNativeVersion(LEGACY_ID,{version_request_id:started.version.version_id,archives:ids},actor);f.id=LEGACY_ID;await enable(f);f.sql.prepare('DELETE FROM app_state WHERE key=?').run('site_archive_v1:'+ids.source_bundle);const before=snapshot(f.sql);await assert.rejects(()=>plan(f));assert.deepEqual(snapshot(f.sql),before);assert.equal(f.r2.deletedKeys.length,0);});


for(const phase of ['plan','claim'])for(const [name,mutate] of [
 ['running preparation stage',f=>f.sql.prepare("UPDATE production_stages SET status='running',result='{}' WHERE job_id=?").run(f.id)],
 ['unexpired review lease',f=>f.sql.prepare('UPDATE production_milestones SET review_until=? WHERE id=?').run(Date.now()+60000,f.cover.id)],
 ['historical AI review still running',f=>f.sql.prepare("INSERT INTO production_milestones(id,job_id,node,revision,artifact_version,artifact_hash,artifact,status,mode_epoch,created_at,updated_at) VALUES('SYNTHETIC-history-AI-review',?,'source',1,0,?,'{}','ai_running',0,'now','now')").run(f.id,hash('{}'))]
 ])test('exact five-role '+phase+' waits for '+name+' and never deletes files',async t=>{const f=await acceptedFixture(t);await enable(f);const prepared=phase==='claim'?await plan(f):null;mutate(f);const before=snapshot(f.sql),keys=[...f.r2.map.keys()];await assert.rejects(phase==='plan'?()=>plan(f):()=>p.applySiteRetention(f.id,{plan_id:prepared.plan_id,max_objects:16},actor),status(409));assert.deepEqual(snapshot(f.sql),before);assert.deepEqual([...f.r2.map.keys()],keys);assert.equal(f.r2.deletedKeys.length,0);});

for(const [coverApproval,promotionApproval] of [['website','website'],['website','oral'],['oral','website']])test('five-role cleanup accepts actual '+coverApproval+' cover and '+promotionApproval+' promotion while preserving website approvals',async t=>{
 const f=await acceptedFixture(t,{coverApproval,promotionApproval}),before=await p.getJob(f.id);assertWebsiteApprovalsUnchanged(f);const proof=await p.completedOwnerPostVideoDelivery(before,OWNER);assert.ok(proof);for(const saved of Object.values(f.websiteApprovals))assert.ok(proof.review_rows.some(r=>r.id===saved.review.id));await enable(f);const prepared=await plan(f);assert.deepEqual(Object.keys(prepared.keep).sort(),[...FIVE].sort());assert.deepEqual(prepared.candidates.map(c=>c.site_archive_id),[f.oldVideoSid]);const done=await finish(f,prepared);assert.equal(done.status,'protected');assert.equal(keysFor(f,f.oldVideoSid).length,0);assert.ok(keysFor(f,f.sourceSid).length>0);await assertFiveReadable(f);assertWebsiteApprovalsUnchanged(f);const after=await p.getJob(f.id);assert.deepEqual(protectedJob(after),protectedJob(before));assert.ok(await p.completedOwnerPostVideoDelivery(after,OWNER));assert.equal(after.publication_reports.length,0);assert.ok(f.db.maxBindArgs<=100);
});

for(const node of ['cover','promotion'])for(const [name,mutate] of [
 ['nonempty reason',r=>r.reason='SYNTHETIC changed opinion'],
 ['invalid operation UUID',r=>r.operation_id='SYNTHETIC-not-a-UUID'],
 ['additional oral label',r=>r.source='owner-oral-report']
])test('retention refuses coherently changed website '+node+' report: '+name,async t=>{const f=await acceptedFixture(t,{coverApproval:'website',promotionApproval:'website'});await enable(f);tamperWebsiteReport(f,node,mutate);const before=snapshot(f.sql),keys=[...f.r2.map.keys()];assert.equal(await p.completedOwnerPostVideoDelivery(await p.getJob(f.id),OWNER),null);await assert.rejects(()=>plan(f),status(409));assert.deepEqual(snapshot(f.sql),before);assert.deepEqual([...f.r2.map.keys()],keys);assert.equal(f.r2.deletedKeys.length,0);});

for(const phase of ['plan','claim'])for(const [name,mutate] of [
 ['missing actual owner cover approval',f=>f.sql.prepare('DELETE FROM production_reviews WHERE id=?').run(f.websiteApprovals.cover.review.id)],
 ['foreign reviewer on promotion approval',f=>f.sql.prepare('UPDATE production_reviews SET reviewer=? WHERE id=?').run('SYNTHETIC-other',f.websiteApprovals.promotion.review.id)],
 ['withdrawn private scope',f=>f.sql.prepare("UPDATE app_state SET value=json_set(value,'$.scope.scope','preparation') WHERE key=?").run('media_scope_v1:'+f.id)]
])test('website-approved cleanup '+phase+' refuses '+name,async t=>{const f=await acceptedFixture(t,{coverApproval:'website',promotionApproval:'website'});await enable(f);const prepared=phase==='claim'?await plan(f):null;mutate(f);const before=snapshot(f.sql),keys=[...f.r2.map.keys()];await assert.rejects(phase==='plan'?()=>plan(f):()=>p.applySiteRetention(f.id,{plan_id:prepared.plan_id,max_objects:16},actor),status(409));assert.deepEqual(snapshot(f.sql),before);assert.deepEqual([...f.r2.map.keys()],keys);assert.equal(f.r2.deletedKeys.length,0);});

for(const phase of ['plan','claim'])test('website owner approval withdrawal at actual retention '+phase+' CAS prevents physical deletion',async t=>{const f=await acceptedFixture(t,{coverApproval:'website',promotionApproval:'website'});await enable(f);const prepared=phase==='claim'?await plan(f):null;let raced;f.db.beforeMutation=()=>{f.sql.prepare('DELETE FROM production_reviews WHERE id=?').run(f.websiteApprovals.promotion.review.id);raced=snapshot(f.sql);};await assert.rejects(phase==='plan'?()=>plan(f):()=>p.applySiteRetention(f.id,{plan_id:prepared.plan_id,max_objects:16},actor),status(409));assert.ok(raced,'real retention mutation boundary was reached');assert.deepEqual(snapshot(f.sql),raced);assert.equal(f.r2.deletedKeys.length,0);});

test('GLM website-approved materials still require current editorial authority before cleanup',async t=>{const f=await acceptedFixture(t,{glm:true,coverApproval:'website',promotionApproval:'website'});await enable(f);const prepared=await plan(f);await p.revokeOwnerEditorialDelivery(f.id,OWNER,{request_id:'SYNTHETIC-mixed-web-approval-revoke',authorization_id:f.editorialId,note:'SYNTHETIC actual owner withdraws editorial authority after website material approvals'});const before=snapshot(f.sql);await assert.rejects(()=>p.applySiteRetention(f.id,{plan_id:prepared.plan_id,max_objects:16},actor),status(409));assert.deepEqual(snapshot(f.sql),before);assertWebsiteApprovalsUnchanged(f);assert.equal(f.r2.deletedKeys.length,0);});
